        id: 'q_geo_r4_3_q3',
        label: `問3　資料2の下段について述べた次の文中の空欄Ｘ・Ｙに入る語句の組合せとして最も適当なものを、後の①〜⑥のうちから一つ選べ。

1975年から2020年にかけて、田と畑・樹園地の合計面積は800haから320haへ減少し、かわって耕作放棄地が20haから400haへ増加した。田・畑・樹園地と耕作放棄地の合計を「かつて農地として利用されていた土地」とみなすと、2020年にそのうち耕作放棄地が占める割合は約Ｘである。また、森林面積は8,900haから8,980haへとほとんど変化していないが、Ｙ。`,
